import{_ as s,l as i,o as a,c as n,v as t,p as l,x as o,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Rope","description":"","frontmatter":{"title":"Rope","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rope-structure.md","filePath":"cs/rope-structure.md","lastUpdated":1789023840000}'),h={name:"cs/rope-structure.md"};function m(u,e,A,_,T,f){const r=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="rope" tabindex="-1">Rope <a class="header-anchor" href="#rope" aria-label="Permalink to &quot;Rope&quot;">​</a></h1><div class="epigraph"><p>大串拆成叶上的短块，内部节点只记长度；拼接与分裂走平衡树，不必整缓冲 memcpy。</p><footer>—— 据 Boehm, Atkinson and Plass, Ropes: An Alternative to Strings, Software: Practice and Experience, 1995；Okasaki, Purely Functional Data Structures 整理</footer></div><p><a href="/cs/string-hashing">上一课</a> 的前缀表在插入中间字符时整表作废。<a href="/cs/array-random-access">数组</a> 中间插入 \\(\\Theta(n)\\)。<a href="/cs/persistent-segment-tree">可持久化线段树</a> 已演示路径复制。本课不滚动窗口。缺口是 Rope：把字符串当可并序列树（常平衡 BST / treap），叶存片段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编辑器、版本化文档：拼接、切区间、插删中间。连续 <code>char[]</code> 每次搬移。Rope：二叉树，节点 <code>len</code> = 子树字符数，叶是不可变小串。<code>concat</code> 建新根（可共享子树）；<code>split</code> 按 rank 切开，同<a href="/cs/order-statistic-tree">顺序统计</a> 与隐式 treap。缺口是<strong>把下标当键的可持久序列</strong>，字符比较按叶扫描或再挂哈希。</p><p><span class="marginnote">Boehm et al., <em>SPE</em>, 1995（Cedar / SGI 实践）。函数式语言里同构于树状序列。Okasaki 给持久拼接的摊还图像。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>索引 \\(i\\)：用 <code>len</code> 向左或向右减。平衡：Treap 优先级或 AVL 高度，避免退化成链。扁平化：过小叶合并，过大叶再切，控制常数。可持久：concat/split 不写旧节点。</p>',8)),(a(),l(d,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%B7%A6%20Rope%22%5D%20--%3E%20CAT%5B%22%E6%96%B0%E6%A0%B9%20len%20%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20R%5B%22%E5%8F%B3%20Rope%22%5D%20--%3E%20CAT%0A%20%20CAT%20--%3E%20SHARE%5B%22%E5%AD%90%E6%A0%91%E5%8F%AF%E5%85%B1%E4%BA%AB%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 HAMT：Rope 按位置；下一课 HAMT 按哈希路径存映射。与后缀数组：Rope 动态，SA 静态。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单次索引 \\(O(\\log n)\\) 节点再加叶内偏移。遍历全串 \\(\\Theta(n)\\) 但 cache 不如一块缓冲。哈希可挂在节点上做 \\(O(\\log n)\\) 取子串哈希，接上一课。不要用 Rope 当小串默认类型——阈值以下仍数组。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 gap buffer、piece table 写完，只点名同问题的其他表示。并发编辑 OT/CRDT 不是 Rope 合同。哈希数组映射树下一课换「键→值」持久字典。</p><p>后课默认：大串编辑用 Rope/piece table。持久哈希映射用 HAMT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rope：树状串，concat/split 对数，可共享。</li><li>叶为短块；小串仍用数组。</li><li>下一课 HAMT 是持久字典，不是串。</li><li>出处：Boehm, Atkinson and Plass, <em>SPE</em>, 1995；Okasaki。</li></ul>',8))])}const R=s(h,[["render",m]]);export{B as __pageData,R as default};
